"""Pydantic model for validated ESTD generated news."""
from datetime import datetime, timezone
from typing import Optional

from pydantic import BaseModel, ConfigDict, Field, HttpUrl

from backend.common.constants.categories import ESTDCategory


class GeneratedNews(BaseModel):
    """Structured, fact-grounded news article generated by Gemini AI."""

    model_config = ConfigDict(
        use_enum_values=True,
        populate_by_name=True,
        extra="ignore",
    )

    title: str = Field(
        ...,
        min_length=5,
        max_length=300,
        description="Clear, professional headline summarizing the development.",
    )
    subtitle: Optional[str] = Field(
        default=None,
        max_length=400,
        description="Informative subtitle providing context and secondary details.",
    )
    category: ESTDCategory = Field(
        ...,
        description="Official ESTD news category strictly matching input category.",
    )
    subcategory: Optional[str] = Field(
        default=None,
        max_length=200,
        description="Official ESTD news subcategory matching input or classification.",
    )
    summary: str = Field(
        ...,
        min_length=20,
        max_length=3000,
        description="Concise 2-4 paragraph executive brief of key facts.",
    )
    content: str = Field(
        ...,
        min_length=100,
        description="Comprehensive article body strictly synthesizing source facts without speculation.",
    )
    source_name: str = Field(
        ...,
        min_length=1,
        max_length=255,
        description="Name of the original publisher or news outlet.",
    )
    source_url: str = Field(
        ...,
        description="Exact URL of the source article for full attribution and traceability.",
    )
    generated_at: datetime = Field(
        default_factory=lambda: datetime.now(timezone.utc),
        description="UTC timestamp of content generation.",
    )
